// Prints only the section with the given element id (hides sidebar, filters,
// other tabs, and action buttons marked with the "no-print" class).
function printSection(elementId) {
  document.querySelectorAll('.print-target-active').forEach((el) => el.classList.remove('print-target-active'));
  const el = document.getElementById(elementId);
  if (el) el.classList.add('print-target-active');
  setTimeout(() => window.print(), 50);
}
