// ============================================================================
// SHARED FINANCIAL CALCULATION HELPERS
// ============================================================================
function getDateRangeStart(rangeKey) {
  if (rangeKey === 'all' || !rangeKey) return null;
  if (rangeKey === 'today') {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    return d;
  }
  const daysMap = { '7d': 7, '30d': 30, '90d': 90 };
  const days = daysMap[rangeKey];
  if (!days) return null;
  const d = new Date();
  d.setDate(d.getDate() - days);
  return d;
}

function filterTransactionsByRange(transactions, rangeKey, customFrom, customTo) {
  if (rangeKey === 'custom') {
    if (!customFrom) return transactions;
    const start = new Date(customFrom);
    start.setHours(0, 0, 0, 0);
    const end = customTo ? new Date(customTo) : new Date(customFrom);
    end.setHours(23, 59, 59, 999);
    return transactions.filter((t) => {
      const d = new Date(t.date);
      return d >= start && d <= end;
    });
  }
  const start = getDateRangeStart(rangeKey);
  if (!start) return transactions;
  return transactions.filter((t) => new Date(t.date) >= start);
}

// Net profit per counter = Deposits - Expenses, then split by that counter's own ratio
// A transaction is "direct" when it's Online mode, tagged to a partner, that
// partner is linked to THIS transaction's counter (any % > 0), AND the counter
// itself has "onlineHandledByPartners" enabled. Such transactions bypass the
// normal counter -> owner-share -> pooled-partner-split pipeline entirely and
// instead adjust that partner's balance directly with the FULL amount
// (deposit = credit, expense = debit) - not prorated by their %.
// A transaction is "direct" when it's Online mode, tagged to a partner, the counter
// has "onlineHandledByPartners" enabled, and that partner is in the counter's
// linkedPartnerIds list. Such transactions bypass counter P&L entirely and
// instead adjust that partner's balance directly with the FULL amount
// (deposit = credit, expense = debit).
function isDirectPartnerTransaction(t, counters) {
  if (t.mode !== 'online' || !t.partnerId) return false;
  const counter = counters.find((c) => c.id === t.counterId);
  if (!counter || !counter.onlineHandledByPartners) return false;
  return (counter.linkedPartnerIds || []).includes(t.partnerId);
}

function computeCounterPnL(counter, transactions) {
  // Exclude direct-tagged transactions so they don't get double-counted.
  const counterTx = transactions.filter((t) => t.counterId === counter.id && !isDirectPartnerTransaction(t, [counter]));
  const deposits = counterTx.filter((t) => t.type !== 'expense').reduce((s, t) => s + (t.amount || 0), 0);
  const expenses = counterTx.filter((t) => t.type === 'expense').reduce((s, t) => s + (t.amount || 0), 0);
  const netProfit = deposits - expenses;
  const counterSharePercent = counter.counterSharePercent ?? 60;
  const ownerSharePercent = counter.ownerSharePercent ?? (100 - counterSharePercent);
  const counterShare = netProfit * (counterSharePercent / 100);
  const ownerShare = netProfit * (ownerSharePercent / 100);
  return {
    counterId: counter.id,
    name: counter.name,
    deposits,
    expenses,
    netProfit,
    counterSharePercent,
    ownerSharePercent,
    counterShare,
    ownerShare,
    transactionCount: counterTx.length
  };
}

function computeAllCountersPnL(counters, transactions) {
  return counters.map((c) => computeCounterPnL(c, transactions));
}

// Sums this partner's direct-tagged online transactions (deposit = +, expense = -)
// within an optional date range. Pass rangeKey='all' (default) for all-time.
function computePartnerDirectActivity(partner, allTransactions, counters, rangeKey = 'all', customFrom, customTo) {
  const rangeTx = filterTransactionsByRange(allTransactions, rangeKey, customFrom, customTo);
  const directTx = rangeTx.filter((t) => t.partnerId === partner.id && isDirectPartnerTransaction(t, counters));
  const deposits = directTx.filter((t) => t.type !== 'expense').reduce((s, t) => s + (t.amount || 0), 0);
  const expenses = directTx.filter((t) => t.type === 'expense').reduce((s, t) => s + (t.amount || 0), 0);
  return { deposits, expenses, net: deposits - expenses, count: directTx.length, transactions: directTx };
}

// Partner balance is now purely: Opening Balance + Direct Online Activity - Withdrawn.
// There is no more pooled/percentage-based profit sharing.
function computePartnerBalances(partners, partnerWithdrawals, allTransactions, counters) {
  return partners.map((p) => {
    const withdrawn = partnerWithdrawals
      .filter((w) => w.partnerId === p.id)
      .reduce((s, w) => s + (w.amount || 0), 0);
    const opening = p.openingBalance || 0;
    const directActivity = computePartnerDirectActivity(p, allTransactions, counters, 'all');
    const available = opening + directActivity.net - withdrawn;
    return { ...p, withdrawn, opening, directNet: directActivity.net, available };
  });
}

// ============================================================================
// AUTHENTICATION COMPONENT (Login only - accounts are created by Admin)
// ============================================================================
const AuthComponent = ({ onAuthSuccess }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const handleAuth = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      const result = await signInWithEmailAndPassword(auth, email, password);
      const userSnap = await get(ref(database, `users/${result.user.uid}`));
      const userData = userSnap.val();

      if (userData && userData.status === 'active') {
        onAuthSuccess({
          uid: result.user.uid,
          email: email,
          role: userData.role,
          counters: userData.counters || [],
          name: userData.name || email.split('@')[0]
        });
        toast.success(`Welcome, ${userData.name || 'User'}!`);
      } else if (userData && userData.status !== 'active') {
        toast.error('Account is inactive. Contact admin.');
        await signOut(auth);
      } else {
        toast.error('No account found. Contact your admin to get access.');
        await signOut(auth);
      }
    } catch (error) {
      toast.error(error.message);
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-orange-50 to-red-50 dark:from-gray-900 dark:to-gray-800 flex items-center justify-center p-4">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="w-full max-w-md"
      >
        <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl p-8">
          <div className="text-center mb-8">
            <div className="text-4xl font-bold text-orange-600 dark:text-orange-400 mb-2">
              🍜 {APP_NAME}
            </div>
            <p className="text-gray-600 dark:text-gray-400">Restaurant Management Dashboard</p>
          </div>

          <form onSubmit={handleAuth} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Email</label>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500 dark:bg-gray-700 dark:text-white"
                placeholder="your@email.com"
                required
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Password</label>
              <div className="relative">
                <input
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500 dark:bg-gray-700 dark:text-white"
                  placeholder="••••••••"
                  required
                />
                <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-500">
                  {showPassword ? <FiEyeOff /> : <FiEye />}
                </button>
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-gradient-to-r from-orange-500 to-red-500 hover:from-orange-600 hover:to-red-600 text-white font-bold py-3 rounded-lg transition transform hover:scale-105 disabled:opacity-50"
            >
              {loading ? 'Signing in...' : 'Sign In'}
            </button>

            <p className="text-center text-xs text-gray-500 dark:text-gray-400 pt-2">
              Don't have an account? Contact your admin to get access.
            </p>
          </form>

          <div className="mt-8 pt-8 border-t border-gray-200 dark:border-gray-700 text-center text-xs text-gray-500 dark:text-gray-400">
            {CREDIT}
          </div>
        </div>
      </motion.div>
    </div>
  );
};

